    fun get(lang: JarvisLanguage, key: String): String =
        entries[key]?.get(lang.ordinal) ?: error("Missing update language key " + key)
    fun valid(): Boolean = entries.values.all { it.size == JarvisLanguage.entries.size && it.all(String::isNotBlank) }
